cssCode:
.black-hole {
  position: relative;
  width: 160px; height: 160px;
  border-radius: 50%;
  background: radial-gradient(circle, #000000 30%, #1a0033 70%, #4b0082 100%);
  box-shadow: 0 0 50px 10px #4b0082, inset 0 0 20px #000000;
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), filter 0.3s ease;
  cursor: pointer;
  z-index: 10;
}
.black-hole::after {
  content: "";
  position: absolute;
  top: -40px; left: -40px; right: -40px; bottom: -40px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.05);
  border-top: 4px solid #00ffff;
  border-bottom: 4px solid #ff00ff;
  animation: spinHole 3s linear infinite;
}
@keyframes spinHole { 100% { transform: rotate(360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:#010008;display:flex;align-items:center;justify-content:center;overflow:hidden;';

const hole = document.createElement('div');
hole.className = 'black-hole';
c.appendChild(hole);

let hueVal = 0;

// દરેક ટચ પર અલગ પ્રતિક્રિયા
c.addEventListener('pointerdown', () => {
  hueVal += 75; // દર વખતે 75 ડિગ્રી કલર બદલાશે
  hole.style.filter = `hue-rotate(${hueVal}deg) brightness(1.5)`;
  hole.style.transform = `scale(1.4)`;
  hole.style.boxShadow = `0 0 100px 30px #4b0082`;

  setTimeout(() => {
    hole.style.transform = `scale(1)`;
    hole.style.filter = `hue-rotate(${hueVal}deg) brightness(1)`;
    hole.style.boxShadow = `0 0 50px 10px #4b0082`;
  }, 350);
});
